import type { TopicDetail } from "./topic-detail-types";

function detail(
  core: string,
  mathConnection: string,
  exampleTitle: string,
  explanation: string,
  tryIt: string,
  question: string,
  answer: string,
): TopicDetail {
  return {
    core,
    mathConnection,
    example: { title: exampleTitle, explanation, tryIt },
    quiz: { question, answer },
  };
}

